3	/** Subdivisions per frame. 1s @ 30fps = 30 * 30 = 900 ticks. See GLOSSARY.md "Tick". */
4	export const DEFAULT_TICK_RESOLUTION = 30;
5	
6	export function toTick(value: number): Tick {
7	  return Math.round(value) as Tick;
8	}
9	
10	export function ticksPerSecond(
11	  fps: number,
12	  tickResolution: number = DEFAULT_TICK_RESOLUTION,
13	): number {
14	  return fps * tickResolution;
15	}
16	
17	export function ticksToSeconds(
18	  tick: Tick,
19	  fps: number,
20	  tickResolution: number = DEFAULT_TICK_RESOLUTION,
21	): number {
22	  return tick / ticksPerSecond(fps, tickResolution);
23	}
24	
25	export function secondsToTicks(
26	  seconds: number,
27	  fps: number,
28	  tickResolution: number = DEFAULT_TICK_RESOLUTION,
29	): Tick {
30	  return toTick(seconds * ticksPerSecond(fps, tickResolution));
